const booking = $('Receive Clinic Booking').first().json.body;
const doctor = $('Find Selected Doctor').first().json;

const date = booking.appointmentDate;
const time = booking.appointmentTime;

const duration = Number(doctor.durationMinutes);
const opening = String(doctor.openingTime).slice(0, 5);
const closing = String(doctor.closingTime).slice(0, 5);

const pad = n => String(n).padStart(2, '0');

if (!date || !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
  throw new Error('Invalid appointment date');
}

if (!time || !/^([01]\d|2[0-3]):[0-5]\d$/.test(time)) {
  throw new Error('Invalid appointment time');
}

if (!Number.isInteger(duration) || duration <= 0) {
  throw new Error('Invalid doctor appointment duration');
}

if (doctor.active === false ||
    String(doctor.active).toUpperCase() === 'FALSE') {
  throw new Error('Doctor is inactive');
}

const start = new Date(`${date}T${time}:00+05:30`);

if (
  Number.isNaN(start.getTime()) ||
  start.toISOString().slice(0, 10) !== date
) {
  throw new Error('Invalid calendar date');
}

const end = new Date(start.getTime() + duration * 60000);

const startMinutes =
  Number(time.slice(0, 2)) * 60 +
  Number(time.slice(3, 5));

const endMinutes = startMinutes + duration;

const openingMinutes =
  Number(opening.slice(0, 2)) * 60 +
  Number(opening.slice(3, 5));

const closingMinutes =
  Number(closing.slice(0, 2)) * 60 +
  Number(closing.slice(3, 5));

if (
  !Number.isFinite(openingMinutes) ||
  !Number.isFinite(closingMinutes) ||
  openingMinutes >= closingMinutes
) {
  throw new Error('Invalid doctor working hours');
}

if (
  startMinutes < openingMinutes ||
  endMinutes > closingMinutes
) {
  return [{
    json: {
      ...booking,
      doctorName: doctor.doctorName,
      availableHours: false,
      message: 'Appointment is outside the doctor working hours'
    }
  }];
}

const requestedDay = new Date(
  `${date}T12:00:00+05:30`
).toLocaleDateString('en-US', {
  weekday: 'long',
  timeZone: 'Asia/Kolkata'
});

const workingDays = String(doctor.workingDays)
  .split(',')
  .map(d => d.trim());

if (!workingDays.includes(requestedDay)) {
  return [{
    json: {
      ...booking,
      doctorName: doctor.doctorName,
      availableHours: false,
      message: 'Doctor does not work on this day'
    }
  }];
}

if (start.getTime() <= Date.now()) {
  return [{
    json: {
      ...booking,
      doctorName: doctor.doctorName,
      availableHours: false,
      message: 'Appointment must be in the future'
    }
  }];
}

const endLocal = new Date(end.getTime() + 330 * 60000);

const appointmentEndDate =
  `${endLocal.getUTCFullYear()}-` +
  `${pad(endLocal.getUTCMonth() + 1)}-` +
  `${pad(endLocal.getUTCDate())}`;

const appointmentEndTime =
  `${pad(endLocal.getUTCHours())}:` +
  `${pad(endLocal.getUTCMinutes())}`;

return [{
  json: {
    ...booking,
    doctorName: doctor.doctorName,
    durationMinutes: duration,
    appointmentStart: start.toISOString(),
    appointmentEnd: end.toISOString(),
    appointmentEndDate,
    appointmentEndTime,
    availableHours: true
  }
}];

const booking = $('Calculate Appointment Interval').first().json;
const rows = $input.all().map(item => item.json);

if (booking.availableHours !== true) {
  return [{
    json: {
      ...booking,
      slotAvailable: false,
      message: booking.message || 'Appointment time is invalid'
    }
  }];
}

const start = new Date(booking.appointmentStart).getTime();
const end = new Date(booking.appointmentEnd).getTime();

const conflicts = rows.filter(row => {
  if (!row.bookingId || !row.appointmentTime) return false;
  if (String(row.doctorId) !== String(booking.doctorId)) return false;

  const status = String(row.status || '').toLowerCase();

  if (!['pending', 'confirmed'].includes(status)) return false;

  const rowStart = new Date(
    `${row.appointmentDate}T${row.appointmentTime}:00+05:30`
  ).getTime();

  const rowEnd = new Date(
    `${row.appointmentDate}T${row.endTime}:00+05:30`
  ).getTime();

  if (!Number.isFinite(rowStart) || !Number.isFinite(rowEnd)) {
    throw new Error('An existing appointment has an invalid date or time');
  }

  return start < rowEnd && end > rowStart;
});

return [{
  json: {
    ...booking,
    slotAvailable: conflicts.length === 0,
    message: conflicts.length === 0
      ? 'Requested slot is available'
      : 'This appointment time is already booked'
  }
}];

