const booking = $input.first().json;

const appointmentDate = String(booking.appointmentDate ?? '');
const appointmentTime = String(booking.appointmentTime ?? '');

const duration = Number(booking.durationMinutes ?? 30);

if (!booking.patientName || !booking.email || !booking.doctorId) {
  throw new Error('Missing required patient, email, or doctor information.');
}

if (!/^\d{4}-\d{2}-\d{2}$/.test(appointmentDate)) {
  throw new Error('Invalid appointment date.');
}

if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(appointmentTime)) {
  throw new Error('Invalid appointment time.');
}

const [year, month, day] = appointmentDate.split('-').map(Number);
const dateCheck = new Date(Date.UTC(year, month - 1, day));

if (
  dateCheck.getUTCFullYear() !== year ||
  dateCheck.getUTCMonth() !== month - 1 ||
  dateCheck.getUTCDate() !== day
) {
  throw new Error('Invalid calendar date.');
}

const [hour, minute] = appointmentTime.split(':').map(Number);
const startMinutes = hour * 60 + minute;
const endMinutes = startMinutes + duration;

if (!Number.isInteger(duration) || duration <= 0 || endMinutes >= 1440) {
  throw new Error('Invalid appointment duration.');
}

const pad = n => String(n).padStart(2, '0');
const endTime =
  `${pad(Math.floor(endMinutes / 60))}:${pad(endMinutes % 60)}`;

const bookingId = booking.bookingId || `BOOK-${Date.now()}`;

return [{
  json: {
    ...booking,
    bookingId,
    appointmentDate,
    appointmentTime,
    endTime,
    appointmentStart: `${appointmentDate}T${appointmentTime}:00+05:30`,
    appointmentEnd: `${appointmentDate}T${endTime}:00+05:30`,
    status: 'confirmed',
    calendarEventId: '',
    emailStatus: 'not_sent',
    whatsappStatus: 'not_sent',
    reminderSent: false,
    createdAt: new Date().toISOString()
  }
}];

return $input.all().filter(item => {
  const row = item.json;

  return (
    String(row.status || '').trim().toLowerCase() === 'confirmed' &&
    String(row.reminderSent || '').trim().toUpperCase() !== 'TRUE' &&
    Boolean(row.email) &&
    Boolean(row.bookingId)
  );
});

