const booking = $input.first().json;
const request = $('Receive Reschedule Request').first().json.body ?? {};

const date = String(request.newAppointmentDate ?? '');
const time = String(request.newAppointmentTime ?? '');

const validDateFormat = /^\d{4}-\d{2}-\d{2}$/.test(date);
const validTimeFormat = /^([01]\d|2[0-3]):[0-5]\d$/.test(time);

let validDate = false;
let validFutureDateTime = false;

if (validDateFormat) {
  const [year, month, day] = date.split('-').map(Number);
  const parsedDate = new Date(Date.UTC(year, month - 1, day));

  validDate =
    parsedDate.getUTCFullYear() === year &&
    parsedDate.getUTCMonth() === month - 1 &&
    parsedDate.getUTCDate() === day;
}

if (validDate && validTimeFormat) {
  const [year, month, day] = date.split('-').map(Number);
  const [hour, minute] = time.split(':').map(Number);

  // Convert the requested India time (UTC+05:30) to UTC.
  const appointmentTimestamp = Date.UTC(
    year, month - 1, day, hour, minute
  ) - (5 * 60 + 30) * 60 * 1000;

  validFutureDateTime = appointmentTimestamp > Date.now();
}

const bookingExists =
  Boolean(booking.bookingId) &&
  booking.bookingId === request.bookingId;

const emailMatches =
  String(booking.email ?? '').trim().toLowerCase() ===
  String(request.email ?? '').trim().toLowerCase();

const isConfirmed =
  String(booking.status ?? '').trim().toLowerCase() === 'confirmed';

const hasCalendarEvent =
  String(booking.calendarEventId ?? '').trim() !== '';

let validationMessage = 'Request valid';

if (!bookingExists) {
  validationMessage = 'Booking not found';
} else if (!emailMatches) {
  validationMessage = 'Email does not match the booking';
} else if (!isConfirmed) {
  validationMessage = 'Booking is not confirmed';
} else if (!hasCalendarEvent) {
  validationMessage = 'Calendar event ID is missing';
} else if (!validDate || !validTimeFormat || !validFutureDateTime) {
  validationMessage = 'New appointment date or time is invalid or in the past';
}

const valid =
  bookingExists &&
  emailMatches &&
  isConfirmed &&
  hasCalendarEvent &&
  validDate &&
  validTimeFormat &&
  validFutureDateTime;

return [{
  json: {
    ...booking,
    newAppointmentDate: date,
    newAppointmentTime: time,
    valid,
    validationMessage
  }
}];

const booking = $input.first().json;

const [year, month, day] =
  booking.newAppointmentDate.split('-').map(Number);

const [hour, minute] =
  booking.newAppointmentTime.split(':').map(Number);

// Preserve the original appointment duration.
const [oldStartHour, oldStartMinute] =
  booking.appointmentTime.split(':').map(Number);

const [oldEndHour, oldEndMinute] =
  booking.endTime.split(':').map(Number);

const durationMinutes =
  (oldEndHour * 60 + oldEndMinute) -
  (oldStartHour * 60 + oldStartMinute);

if (durationMinutes <= 0) {
  throw new Error('Existing appointment duration is invalid.');
}

const startMinutes = hour * 60 + minute;
const endMinutes = startMinutes + durationMinutes;

if (endMinutes > 24 * 60) {
  throw new Error('Appointment ends after midnight.');
}

const pad = n => String(n).padStart(2, '0');

const endTime =
  `${pad(Math.floor(endMinutes / 60))}:${pad(endMinutes % 60)}`;

return [{
  json: {
    ...booking,
    newEndTime: endTime,
    newStartDateTime:
      `${booking.newAppointmentDate}T${booking.newAppointmentTime}:00+05:30`,
    newEndDateTime:
      `${booking.newAppointmentDate}T${endTime}:00+05:30`
  }
}];

const rows = $input.all().map(item => item.json);
const booking =
  $('Calculate New Appointment Interval').first().json;

const requestedStart =
  new Date(booking.newStartDateTime).getTime();

const requestedEnd =
  new Date(booking.newEndDateTime).getTime();

const conflict = rows.some(row => {
  // Ignore the appointment being rescheduled.
  if (row.bookingId === booking.bookingId) return false;

  // Only check appointments for the same doctor.
  if (row.doctorId !== booking.doctorId) return false;

  // Ignore cancelled appointments.
  if (String(row.status).toLowerCase() !== 'confirmed') {
    return false;
  }

  const existingStart = new Date(
    `${row.appointmentDate}T${row.appointmentTime}:00+05:30`
  ).getTime();

  const existingEnd = new Date(
    `${row.appointmentDate}T${row.endTime}:00+05:30`
  ).getTime();

  return requestedStart < existingEnd &&
         requestedEnd > existingStart;
});

return [{
  json: {
    ...booking,
    slotAvailable: !conflict
  }
}];

